describe('Total Price Update on Quantity Change', () => {
  beforeEach(() => {
    cy.visit('/cart');
  });

  it('should update total price when quantity is increased', () => {
    // Verify initial state
    cy.get('[data-testid="item-price"]').should('contain', '$10.00');
    cy.get('[data-testid="quantity-input"]').should('have.value', '1');
    cy.get('[data-testid="total-price"]').should('contain', '$10.00');

    // Increase quantity
    cy.get('[data-testid="quantity-input"]').clear().type('3');

    // Verify total price updates
    cy.get('[data-testid="total-price"]').should('contain', '$30.00');
    cy.get('[data-testid="item-price"]').should('contain', '$10.00');
    cy.get('[data-testid="quantity-display"]').should('contain', '3');
  });

  it('should update total price when quantity is decreased to zero', () => {
    // Set initial quantity
    cy.get('[data-testid="quantity-input"]').clear().type('5');
    cy.get('[data-testid="total-price"]').should('contain', '$50.00');

    // Decrease quantity
    cy.get('[data-testid="quantity-input"]').clear().type('1');

    // Verify total price updates
    cy.get('[data-testid="total-price"]').should('contain', '$10.00');
    cy.get('[data-testid="quantity-display"]').should('contain', '1');

    // Verify total price is not zero when quantity is 1
    cy.get('[data-testid="total-price"]').should('not.contain', '$0.00');
  });
});
